"""Asymmetric Key Packages dissector (packet-akp.c, generated by asn2wrs
from epan/dissectors/asn1/akp/).

AKP is reached the way a real capture reaches it:

  - HTTP bodies with the media types application/pkcs8 (PrivateKeyInfo, a
    OneAsymmetricKey) and application/pkcs8-encrypted
    (EncryptedPrivateKeyInfo), which call the registered "akp_private_key"
    and "akp_encrypted_private_key" dissectors;
  - HTTP bodies of media type application/pkcs7-mime: a CMS ContentInfo
    whose content type is id-ct-KP-aKeyPackage, id-ct-privateKeyInfo or
    id-ct-encrPrivateKeyInfo, which CMS hands to AKP by OID;
  - attributes of a OneAsymmetricKey (pkcs-9-at-encryptedPrivateKeyInfo,
    id-ct-privateKeyInfo, id-ct-encrPrivateKeyInfo), which hand their value
    to AKP by OID, also nested.

No keys are involved: every private key, signature and encrypted block is
placeholder bytes, and the passphrase based encryption cannot be decrypted
(no password is set), so nothing is decrypted.  The BER syntax names, the
".p8" and ".p8e" file extensions and the rfc7468 labels of the registration
are reached only from a file or by name and cannot be reached from a packet.

Usage: mkakp.py [<output directory>]

Writes akp-coverage.pcap (nothing malformed, no error expert infos) and
akp-coverage-malformed.pcap.  Every packet is built here; nothing comes
from a real network.
"""

import os
import sys

sys.path.insert(1, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'shared'))

import struct  # noqa: E402

from capgen import TcpFlow, write_pcap  # noqa: E402
from repro import reproducer  # noqa: E402

# ---------------------------------------------------------------- BER


def tlv(tag, body):
    n = len(body)
    if n < 0x80:
        ln = bytes([n])
    else:
        b = n.to_bytes((n.bit_length() + 7) // 8, 'big')
        ln = bytes([0x80 | len(b)]) + b
    return bytes([tag]) + ln + body


def oid(dotted):
    p = [int(x) for x in dotted.split('.')]
    out = bytes([p[0] * 40 + p[1]])
    for v in p[2:]:
        b = [v & 0x7f]
        v >>= 7
        while v:
            b.insert(0, 0x80 | (v & 0x7f))
            v >>= 7
        out += bytes(b)
    return tlv(0x06, out)


def seq(*parts):
    return tlv(0x30, b''.join(parts))


def sset(*parts):
    return tlv(0x31, b''.join(parts))


def integer(v):
    n = 1
    while True:
        try:
            return tlv(0x02, v.to_bytes(n, 'big', signed=True))
        except OverflowError:
            n += 1


def octets(b):
    return tlv(0x04, b)


NULL = b'\x05\x00'

OID_RSA = '1.2.840.113549.1.1.1'
OID_EC = '1.2.840.10045.2.1'
OID_P256 = '1.2.840.10045.3.1.7'
OID_ED25519 = '1.3.101.112'
OID_PBES2 = '1.2.840.113549.1.5.13'
OID_PBKDF2 = '1.2.840.113549.1.5.12'
OID_HMAC_SHA256 = '1.2.840.113549.2.9'
OID_AES256_CBC = '2.16.840.1.101.3.4.1.42'
OID_P12_3DES = '1.2.840.113549.1.12.1.3'
OID_FRIENDLY_NAME = '1.2.840.113549.1.9.20'
OID_LOCAL_KEY_ID = '1.2.840.113549.1.9.21'
OID_AT_ENCRYPTED = '1.2.840.113549.1.9.25.2'
OID_CT_PKI = '1.2.840.113549.1.9.16.1.52'
OID_CT_EPKI = '1.2.840.113549.1.9.16.1.53'
OID_CT_AKP = '2.16.840.1.101.2.1.2.78.5'


def alg(dotted, params=None):
    return seq(oid(dotted), params if params is not None else b'')


def pattern(n, seed):
    """Placeholder bytes (not a key)."""
    return bytes((seed * 31 + i * 7) & 0xff for i in range(n))


def attribute(dotted, *values):
    return seq(oid(dotted), sset(*values))


def pki(algid, key, attrs=None, public=None, version=0):
    """PrivateKeyInfo / OneAsymmetricKey: attributes [0], publicKey [1]."""
    body = integer(version) + algid + octets(key)
    if attrs is not None:
        body += tlv(0xa0, b''.join(attrs))
    if public is not None:
        body += tlv(0x81, b'\x00' + public)
    return seq(body)


def epki(algid, data):
    return seq(algid, octets(data))


def pbes2(salt_seed, iterations=2048, prf=True, scheme=OID_AES256_CBC, iv=16):
    kdf_params = octets(pattern(8, salt_seed)) + integer(iterations)
    if prf:
        kdf_params += alg(OID_HMAC_SHA256, NULL)
    return alg(OID_PBES2, seq(alg(OID_PBKDF2, seq(kdf_params)),
                              alg(scheme, octets(pattern(iv, salt_seed + 1)))))


def p12_pbe():
    return alg(OID_P12_3DES, seq(octets(pattern(8, 9)), integer(1024)))


def content_info(content_type, content):
    return seq(oid(content_type), tlv(0xa0, content))


# ---------------------------------------------------------------- the messages

RSA = alg(OID_RSA, NULL)
EC = alg(OID_EC, oid(OID_P256))
ED = alg(OID_ED25519)


def nested(depth, attr_oid=OID_CT_PKI):
    """A PrivateKeyInfo whose attributes carry another PrivateKeyInfo, depth times."""
    inner = pki(ED, pattern(34, 1))
    for _ in range(depth):
        inner = pki(ED, pattern(34, 2), attrs=[seq(oid(attr_oid), sset(inner))])
    return inner


def http_response(ctype, body, status='200 OK'):
    return (('HTTP/1.1 %s\r\nServer: example\r\nContent-Type: %s\r\nContent-Length: %d\r\n\r\n'
             % (status, ctype, len(body))).encode() + body)


def http_request(method, uri, ctype, body):
    return (('%s %s HTTP/1.1\r\nHost: keys.example.com\r\nContent-Type: %s\r\nContent-Length: %d\r\n\r\n'
             % (method, uri, ctype, len(body))).encode() + body)


def build(repro_dir=None):
    clean = []
    malformed = []
    port = [40000]

    def exchange(caps, req, rsp, note):
        flow = TcpFlow(port[0], 80, isn_c=1000 + port[0], isn_s=9000 + port[0])
        port[0] += 1
        # No handshake: a SYN without options is flagged as a scanner
        for fr in (flow.send(req), flow.recv(rsp)):
            caps.append((fr, note))

    def get(caps, ctype, body, note):
        exchange(caps, b'GET /key HTTP/1.1\r\nHost: keys.example.com\r\n\r\n', http_response(ctype, body), note)

    def post(caps, ctype, body, note):
        exchange(caps, http_request('POST', '/upload', ctype, body), http_response('text/plain', b'ok'), note)

    def c(ctype, body, note):
        get(clean, ctype, body, note)

    P8, P8E, P7 = 'application/pkcs8', 'application/pkcs8-encrypted', 'application/pkcs7-mime'

    # ---- PrivateKeyInfo: versions, algorithms, attributes, public key
    c(P8, pki(RSA, pattern(48, 3)), 'PrivateKeyInfo v1, rsaEncryption with NULL parameters')
    post(clean, P8, pki(EC, pattern(32, 4)), 'PrivateKeyInfo v1 in a POST, id-ecPublicKey with a named curve')
    c(P8, pki(ED, pattern(34, 5)), 'PrivateKeyInfo v1, Ed25519 without parameters')
    c(P8, pki(ED, pattern(34, 6), public=pattern(32, 7), version=1),
      'OneAsymmetricKey v2 with a public key')
    c(P8, pki(RSA, pattern(40, 8), attrs=[attribute(OID_FRIENDLY_NAME, tlv(0x1e, 'key'.encode('utf-16-be'))),
                                          attribute(OID_LOCAL_KEY_ID, octets(pattern(4, 9)), octets(pattern(8, 10)))],
              public=pattern(24, 11), version=1),
      'OneAsymmetricKey v2 with two attributes (one with two values) and a public key')
    c(P8, pki(RSA, pattern(16, 12), attrs=[]), 'PrivateKeyInfo with an empty attribute set')
    c(P8, pki(ED, pattern(34, 13), version=5), 'PrivateKeyInfo with an unknown version')
    c(P8, pki(ED, b''), 'PrivateKeyInfo with an empty private key')

    # ---- attributes that carry a key
    c(P8, pki(ED, pattern(34, 14), attrs=[seq(oid(OID_CT_PKI), sset(pki(ED, pattern(34, 15))))]),
      'attribute id-ct-privateKeyInfo: a PrivateKeyInfo inside the attribute')
    c(P8, pki(ED, pattern(34, 16), attrs=[seq(oid(OID_CT_EPKI), sset(epki(pbes2(1), pattern(64, 17))))]),
      'attribute id-ct-encrPrivateKeyInfo: an EncryptedPrivateKeyInfo inside the attribute')
    c(P8, pki(ED, pattern(34, 18), attrs=[seq(oid(OID_AT_ENCRYPTED), sset(epki(p12_pbe(), pattern(48, 19))))]),
      'attribute pkcs-9-at-encryptedPrivateKeyInfo')
    c(P8, nested(10), 'PrivateKeyInfo nested 10 levels deep through id-ct-privateKeyInfo attributes')
    c(P8, nested(5, OID_CT_PKI), 'PrivateKeyInfo nested 5 levels')

    # ---- EncryptedPrivateKeyInfo (the encrypted block is placeholder bytes)
    c(P8E, epki(pbes2(2), pattern(64, 20)), 'EncryptedPrivateKeyInfo, PBES2 with PBKDF2 and AES-256-CBC')
    c(P8E, epki(pbes2(3, iterations=10000, prf=False), pattern(80, 21)),
      'EncryptedPrivateKeyInfo, PBES2 without a PRF')
    c(P8E, epki(p12_pbe(), pattern(48, 22)), 'EncryptedPrivateKeyInfo, PKCS#12 pbeWithSHAAnd3-KeyTripleDES-CBC')
    c(P8E, epki(alg('1.2.3.4.5'), pattern(16, 23)), 'EncryptedPrivateKeyInfo, unknown algorithm')
    c(P8E, epki(pbes2(4), b''), 'EncryptedPrivateKeyInfo, empty encrypted data')
    post(clean, P8E, epki(pbes2(5), pattern(32, 24)), 'EncryptedPrivateKeyInfo in a POST')

    # ---- CMS ContentInfo (application/pkcs7-mime) with the AKP content types
    c(P7, content_info(OID_CT_AKP, seq(pki(RSA, pattern(40, 25)), pki(ED, pattern(34, 26), version=1))),
      'CMS ContentInfo id-ct-KP-aKeyPackage with two keys')
    c(P7, content_info(OID_CT_PKI, pki(EC, pattern(32, 27))), 'CMS ContentInfo id-ct-privateKeyInfo')
    c(P7, content_info(OID_CT_EPKI, epki(pbes2(6), pattern(48, 28))), 'CMS ContentInfo id-ct-encrPrivateKeyInfo')

    # ---- reproducer: nested attributes (OID callback recursion is bounded)
    if repro_dir is not None:
        rep = read_first_exported_pdu(os.path.join(repro_dir, 'akp_nested_attr.pcap'))
        assert rep == nested_repro(), 'akp_nested_attr.pcap does not match the rebuilt payload'
    # 400 levels (as the reproducer) stop at the callback nesting limit with
    # an undecoded-data warning: in the main capture, which has no error
    # expert infos, 40 levels cross the limit of 32 as well
    c(P8, nested(40), 'reproducer akp_nested_attr: 40 levels cross the BER callback nesting limit')
    c(P8, nested_repro(), 'reproducer akp_nested_attr: 400 levels')

    # ------------------------------------------------ malformed capture
    for name, ctype, body in (
            ('PrivateKeyInfo cut after the version', P8, pki(RSA, pattern(40, 30))[:12]),
            ('PrivateKeyInfo cut inside the private key', P8, pki(RSA, pattern(40, 31))[:30]),
            ('PrivateKeyInfo with a negative version length', P8, seq(tlv(0x02, b''), RSA)),
            ('PrivateKeyInfo, not a SEQUENCE', P8, tlv(0x04, b'\x01\x02')),
            ('PrivateKeyInfo, attribute truncated', P8, pki(ED, pattern(34, 32), attrs=[seq(oid(OID_FRIENDLY_NAME))])[:-1]),
            ('EncryptedPrivateKeyInfo cut in the algorithm', P8E, epki(pbes2(7), pattern(32, 33))[:20]),
            ('EncryptedPrivateKeyInfo, encrypted data of the wrong type', P8E, seq(pbes2(8), tlv(0x02, b'\x01'))),
            ('EncryptedPrivateKeyInfo, not a SEQUENCE', P8E, b'\x01\x02\x03'),
            ('CMS id-ct-KP-aKeyPackage with an empty package', P7, content_info(OID_CT_AKP, seq())),
            ('CMS id-ct-KP-aKeyPackage with a truncated key', P7, content_info(OID_CT_AKP, seq(pki(RSA, pattern(40, 34))[:20]))),
            ):
        get(malformed, ctype, body, name)

    return clean, malformed


def nested_repro():
    """The payload of the reproducer: PrivateKeyInfo nested 400 levels deep."""
    alg_rsa = seq(oid(OID_RSA), NULL)
    inner = seq(integer(0), alg_rsa, octets(b'\x01\x02\x03\x04'))
    for _ in range(400):
        attr = seq(oid(OID_CT_PKI), sset(inner))
        inner = seq(integer(0), alg_rsa, octets(b'\x01\x02\x03\x04'), tlv(0xa0, attr))
    return inner


def read_first_exported_pdu(path):
    """The payload of the first Exported PDU frame of a pcap."""
    from capgen import read_pcap
    rec = read_pcap(path)[0]
    p = 0
    while p + 4 <= len(rec):
        t, ln = struct.unpack('!HH', rec[p:p + 4])
        p += 4 + ln
        if t == 0:
            break
    return rec[p:]


def main():
    out = sys.argv[1] if len(sys.argv) > 1 else '.'
    here = os.path.dirname(os.path.abspath(__file__))
    repro = os.path.dirname(reproducer(os.path.join(here, 'akp_nested_attr.py'), 'akp_nested_attr.pcap'))
    clean, malformed = build(repro)
    write_pcap(os.path.join(out, 'akp-coverage.pcap'), [fr for fr, _ in clean])
    write_pcap(os.path.join(out, 'akp-coverage-malformed.pcap'), [fr for fr, _ in malformed])
    print('%d + %d frames' % (len(clean), len(malformed)), file=sys.stderr)


if __name__ == '__main__':
    main()
